/**
 * @mf-eval/media — the asset manifest, typed.
 *
 * Apps import from here rather than hard-coding URLs, which is what lets every `<img>` carry
 * real intrinsic dimensions and a real `srcset` without an author thinking about either.
 * The manifest is generated by `scripts/derive.mjs` from real photographs; see docs/media.md
 * for the profile it is built to match.
 */
import manifestJson from '../manifest.json' with { type: 'json' };

/** One origin for every asset — a stand-in for a DAM or image CDN. */
export const MEDIA_ORIGIN = 'http://localhost:3105';

export interface MediaImage {
  id: string;
  /** Intrinsic size of the LARGEST derivative. Use these for width/height attributes. */
  width: number;
  height: number;
  aspectRatio: number;
  widths: number[];
  bytes: Record<string, { jpeg: number; webp: number; avif: number }>;
  /** Inline 16px placeholder, so a slow image has colour in its box rather than a hole. */
  lqip: string;
  credit: MediaCredit | null;
}

export interface MediaCredit {
  id: string;
  title: string;
  author: string;
  licence: string;
  licenceUrl: string;
  source: string;
}

export interface MediaVideo {
  id: string;
  width: number;
  height: number;
  aspectRatio: number;
  poster: { path: string; width: number; height: number; bytes: number };
  /** Ordered by measured weight — the browser takes the first it supports. */
  sources: { path: string; type: string; bytes: number }[];
  credit: MediaCredit | null;
}

interface Manifest {
  images: Record<string, MediaImage>;
  video: Record<string, MediaVideo>;
  generatedAt: string;
}

export const MEDIA = manifestJson as unknown as Manifest;

export const mediaUrl = (path: string): string => `${MEDIA_ORIGIN}/${path.replace(/^\//, '')}`;

export type MediaFormat = 'avif' | 'webp' | 'jpeg';
const EXTENSION: Record<MediaFormat, string> = { avif: 'avif', webp: 'webp', jpeg: 'jpg' };

/** `srcset` for one format, listing every width that exists for this image. */
export function srcSet(image: MediaImage, format: MediaFormat): string {
  return image.widths
    .map((w) => `${mediaUrl(`img/${image.id}/${w}.${EXTENSION[format]}`)} ${w}w`)
    .join(', ');
}

/** The fallback `src`: the middle derivative, so a browser without srcset is not punished. */
export function fallbackSrc(image: MediaImage): string {
  const w = image.widths[Math.floor(image.widths.length / 2)] ?? 640;
  return mediaUrl(`img/${image.id}/${w}.jpg`);
}

/** Product families map onto the photograph pools. */
export type MediaFamily = 'breaker' | 'controller' | 'ups' | 'sensor' | 'meter' | 'hero';

const PREFIX: Record<MediaFamily, string> = {
  breaker: 'cp-',
  controller: 'ia-',
  ups: 'pc-',
  sensor: 'sm-',
  meter: 'em-',
  hero: 'hero-',
};

/** Every photograph for a family, in a stable order. */
export function imagesFor(family: MediaFamily): MediaImage[] {
  const prefix = PREFIX[family];
  return Object.values(MEDIA.images)
    .filter((i) => i.id.startsWith(prefix))
    .sort((a, b) => a.id.localeCompare(b.id));
}

/**
 * A last-resort photograph, so no call site has to handle "there are no images".
 *
 * If the manifest is empty the derivatives were never built, and every page would render
 * broken boxes — a runtime failure at build time is the better trade.
 */
const FIRST: MediaImage = (() => {
  const [first] = Object.values(MEDIA.images);
  if (!first) {
    throw new Error('@mf-eval/media has no images. Run `pnpm media` to build the derivatives.');
  }
  return first;
})();

/**
 * Deterministic photograph for a product.
 *
 * Sixty products backed by seventeen photographs has to repeat, and repeating STABLY is what
 * matters: the bench navigates to `p-0001` and asserts what it finds there, and a screenshot
 * taken twice has to show the same thing. Hashing the id gives both.
 */
export function imageForProduct(productId: string, family: MediaFamily): MediaImage {
  const pool = imagesFor(family);
  if (pool.length === 0) return FIRST;
  let hash = 0;
  for (let i = 0; i < productId.length; i += 1) hash = (hash * 31 + productId.charCodeAt(i)) >>> 0;
  return pool[hash % pool.length] ?? FIRST;
}

/** The gallery for a product detail page: its own image first, then the rest of its family. */
export function galleryFor(productId: string, family: MediaFamily): MediaImage[] {
  const primary = imageForProduct(productId, family);
  const rest = imagesFor(family).filter((i) => i.id !== primary.id);
  return [primary, ...rest];
}
